
clc; clear; close all;

% Homomorphic Filtering of Q4 Image
% Parameters:
% gamma_H = 4
% gamma_L = 0.9
% D0 = 10

% Read the image
f = imread('HW3Q4_original_image.jpg');

% Convert RGB image to grayscale
if ndims(f) == 3
    f = 0.2989*double(f(:,:,1)) + ...
        0.5870*double(f(:,:,2)) + ...
        0.1140*double(f(:,:,3));
else
    f = double(f);
end

% Normalize image values to the range [0,1]
f = f / 255;

% Define filter parameters
gammaH = 4;
gammaL = 0.9;
D0 = 10;

% Apply logarithmic transform
f_log = log(1 + f);

% Compute the Fourier transform
F = fft2(f_log);
F_shifted = fftshift(F);

% Construct the homomorphic filter H(u,v)
[M, N] = size(f);

% Create frequency coordinate grids
u = 0:M-1;
v = 0:N-1;

% Shift coordinates so the origin is at the center
u = u - floor(M/2);
v = v - floor(N/2);

[V, U] = meshgrid(v, u);

% Compute squared distance from the center frequency
D2 = U.^2 + V.^2;

% Homomorphic filter:
% H(u,v) = (gammaH - gammaL)[1 - exp(-D^2(u,v)/D0^2)] + gammaL
H = (gammaH - gammaL) .* (1 - exp(-D2 ./ (D0^2))) + gammaL;

% Apply the filter in the frequency domain
G_shifted = H .* F_shifted;

% Compute the inverse Fourier transform
G = ifftshift(G_shifted);
g_log = real(ifft2(G));

% Apply the exponential transform
g = exp(g_log) - 1;

% Normalize the filtered image to [0,1]
g = g - min(g(:));
g = g / max(g(:));

% Display the original and filtered images
figure; %[output:20184a98]

subplot(1,2,1); %[output:20184a98]
imagesc(f); %[output:20184a98]
axis image off; %[output:20184a98]
colormap gray; %[output:20184a98]
title('Original Image'); %[output:20184a98]

subplot(1,2,2); %[output:20184a98]
imagesc(g); %[output:20184a98]
axis image off; %[output:20184a98]
colormap gray; %[output:20184a98]
title('Homomorphic Filtered Image'); %[output:20184a98]

% Save the filtered image
% Convert to uint8 before saving
g_uint8 = uint8(255*g);
imwrite(g_uint8, 'Q4_homomorphic_filtered.jpg');


